// Zentrale Konfiguration - hier Modell/Endpunkte/Gewichte aendern.
const inp = $input.first();
// Stundensatz: Formular-Eingabe (pro Kunde) hat Vorrang vor dem branchenunabhaengigen Default.
const _ovRaw = inp.json && (inp.json.stundensatz_override != null ? inp.json.stundensatz_override : (inp.json.body && inp.json.body.stundensatz));
const _ov = Number(_ovRaw);
const _satsBelegt = Number.isFinite(_ov) && _ov > 0;
const _sats = _satsBelegt ? _ov : 60;   // 60 EUR/h = neutraler KMU-Default (UNBELEGT, bitte je Kunde setzen)
// Vorgaenge/Monat (Volumen) - Formular-Eingabe hat Vorrang vor dem Default.
const _volN = Number(inp.json && (inp.json.vorgaenge_override != null ? inp.json.vorgaenge_override : (inp.json.body && inp.json.body.vorgaenge)));
const _volBelegt = Number.isFinite(_volN) && _volN > 0; const _vol = _volBelegt ? _volN : 3;
// Aufbau-/Entwicklungsstunden (einmalig) - Formular-Eingabe hat Vorrang vor dem Default.
const _entN = Number(inp.json && (inp.json.aufbaustunden_override != null ? inp.json.aufbaustunden_override : (inp.json.body && inp.json.body.aufbaustunden)));
const _entBelegt = Number.isFinite(_entN) && _entN > 0; const _ent = _entBelegt ? _entN : 24;
// Verwendung: 'intern' (Default, reine Prozessoptimierung) oder 'verkauf' (externes Produkt) + optional Verkaufspreis.
const _na = String((inp.json && (inp.json.nutzungsart || (inp.json.body && inp.json.body.nutzungsart))) || 'intern').toLowerCase();
const _nutzungsart = (_na === 'verkauf') ? 'verkauf' : 'intern';
const _vpN = Number(inp.json && (inp.json.verkaufspreis_override != null ? inp.json.verkaufspreis_override : (inp.json.body && inp.json.body.verkaufspreis)));
const _verkaufspreis = (Number.isFinite(_vpN) && _vpN > 0) ? _vpN : null;
return [{
  json: { ...inp.json, config: {
    // LLM (LM Studio, OpenAI-kompatibel). Standard: qwen3-235b-a22b-2507 (MLX, 512GB).
    // Schnellere Alternativen: 'nemotron-cascade-2-30b-a3b' oder 'openai/gpt-oss-20b'
    llm_url:   'http://100.120.133.22:1234/v1/chat/completions',
    llm_model: 'qwen/qwen3-235b-a22b-2507',
    whisper_url:   'http://100.120.133.22:8000/transcribe',
    gotenberg_url: 'http://gotenberg:3000/forms/chromium/convert/html',
    // Bild-PDF-Fallback (nicht maschinenlesbare PDFs): Rasterung + Vision-OCR
    rasterize_url: 'http://100.120.133.22:5001/pdf2png',
    vlm_model: 'qwen/qwen3-vl-30b',
    temperature: 0,
    thresholds: { audio_min_sek: 120, pdf_max_mb: 50, audio_exts: ['mp3','wav','m4a','ogg'], pdf_min_chars: 200 },
    // Aggregationsgewichte N08a (Summe = 1.0)
    gewichte: { N02: 0.20, N03: 0.15, N05: 0.30, N06: 0.20, N07: 0.15 },
    // === Wirtschafts-Parameter (EINE Quelle der Wahrheit; aus Quellen extrahierte Werte haben Vorrang) ===
    params: {
      stundensatz_eur: _sats, stundensatz_belegt: _satsBelegt,  // Formular-Eingabe > Default 60; belegter Quellwert hat in N05a weiter Vorrang
      // af = Anteil der freigesetzten Zeit, der REAL in abrechenbare Arbeit fliesst. BAND statt Punktwert,
      // weil es eine Auslastungs-ANNAHME ist (NIE 1.0 als Default). Deterministisch aus Fakten + Band gerechnet.
      af_szenarien:     { konservativ: 0.2, real: 0.4, optimistisch: 0.7 },  // nicht ausgelastet
      af_szenarien_eng: { konservativ: 0.4, real: 0.6, optimistisch: 0.85 }, // ausgelastet (dreht Auftraege ab)
      kapazitaet_ausgelastet: false, // true -> hoeheres af-Band gerechtfertigt (verdraengt reale Arbeit)
      mandate_pro_monat: _vol, mandate_belegt: _volBelegt,       // Formular-Eingabe > Default 3; treibt den Nutzen linear
      entwicklungsstunden: _ent, entwicklungsstunden_belegt: _entBelegt,    // Formular-Eingabe > Default 24; belegte Quellangabe hat in N04/N05a weiter Vorrang
      pflege_stunden_pro_monat: 1,// laufende Eigenleistung (Wartung/Fehlerbehandlung)
      infra_eur_pro_monat: 30,    // anteilige Infrastruktur (Strom/Backup/Abschreibung)
      nutzungsart: _nutzungsart, verkaufspreis: _verkaufspreis,  // intern (Default) vs. verkauf; Preis nur bei Verkauf
      lizenz_eur_pro_monat: 0,    // externe Lizenzen/Cloud (self-hosted i.d.R. 0)
      sens_volumen: [1, 3, 5],    // Sensitivitaet: worst/real/best Mandate pro Monat
      validiert: false            // JC-06 Vergleichstest bestanden? -> erst dann harte Zahlen / >Pilotieren
    }
  } },
  binary: inp.binary
}];

// Bringt die Form-Uploads auf feste Binary-Keys: 'audio' und 'pdf_0','pdf_1',...
const inp = $input.first();
// Binary direkt vom Webhook lesen (robust, falls die Respond-Node die Binaerdaten nicht durchreicht).
let bin = inp.binary || {};
try { const wb = $('Webhook: Analyse-Start').first().binary; if (wb && Object.keys(wb).length) bin = wb; } catch(e){}
const out = {};
let audioKey = null;
const pdfKeys = [];
for (const [k, v] of Object.entries(bin)) {
  const mt = (v.mimeType || '').toLowerCase();
  const fn = (v.fileName || '').toLowerCase();
  if (!audioKey && (mt.startsWith('audio') || /\.(mp3|wav|m4a|ogg)$/.test(fn))) audioKey = k;
  else if (mt.includes('pdf') || fn.endsWith('.pdf')) pdfKeys.push(k);
}
if (audioKey) out.audio = bin[audioKey];
pdfKeys.forEach((k, i) => { out['pdf_' + i] = bin[k]; });
return [{ json: { ...inp.json, _pdf_count: pdfKeys.length }, binary: out }];

// Regelbasierte Eingangspruefung (kein LLM). Setzt json.freigabe + json.fehlerreport.
const inp = $input.first();
const cfg = $('Config').first().json.config;
const t = cfg.thresholds;
const bin = inp.binary || {};
const errors = [];
const audio = bin.audio;
const pdfCount = Number(inp.json._pdf_count || 0);
const has_audio = !!audio;
const has_pdf = pdfCount > 0;
if (has_audio) {
  const fn = (audio.fileName || '').toLowerCase();
  const okExt = t.audio_exts.some(e => fn.endsWith('.' + e)) || (audio.mimeType || '').startsWith('audio');
  if (!okExt) errors.push('Audioformat nicht unterstuetzt (erlaubt: ' + t.audio_exts.join(', ') + ').');
}
// Mindestens eine Eingabe genuegt (Audio ODER PDF) - z.B. nur ein Konzept-PDF.
if (!has_audio && !has_pdf) errors.push('Bitte mindestens eine Audiodatei ODER ein PDF hochladen.');
const freigabe = errors.length === 0;
return [{ json: { ...inp.json, freigabe, has_audio, has_pdf, fehlerreport: errors,
  hinweis_dauer: 'Audiodauer >= ' + (t.audio_min_sek/60) + ' Min und PDF-Maschinenlesbarkeit werden nach N00/N00b geprueft.' },
  binary: bin }];

// Negativfall JC-00: Workflow startet die Analyse NICHT, liefert konkrete Korrekturhinweise.
const j = $input.first().json;
// Dashboard-Status auf 'abgelehnt' setzen, damit das Polling nicht endlos laeuft.
const fs = (function(){ try { return require('fs'); } catch(e){ return null; } })();
let run = null; try { run = $('Run anlegen').first().json.run_id; } catch(e){}
try { if (fs && run) { fs.writeFileSync('/tmp/wc_status_' + run + '.json', JSON.stringify({
  run_id: run, state: 'rejected', pct: 0, done_count: 0, total: 11, nodes: [],
  meldung: 'Eingangspruefung nicht bestanden', korrekturhinweise: (j.fehlerreport || []),
  log: [{ ts: new Date().toLocaleTimeString('de-DE'), msg: 'Eingabe abgelehnt' }] })); } } catch(e){}
return [{ json: { status: 'abgelehnt', unternehmen: j.Unternehmen || '',
  meldung: 'Eingangspruefung nicht bestanden. Bitte korrigieren und erneut hochladen.',
  korrekturhinweise: j.fehlerreport || [] } }];

// Normalisiert die Whisper-Antwort auf {transcript, dauer}.
const w = $('N00 · Whisper Transkription').first().json;
const transcript = w.transcription || w.text ||
  (Array.isArray(w.segments) ? w.segments.map(s => s.text).join(' ') : '');
const dauer = Number(w.duration || w.audio_duration || 0);
return [{ json: { transcript, dauer, quelle: 'audio' } }];

// Genau einer der beiden Zweige laeuft (Audio vorhanden? IF). Lies den gelaufenen, liefere immer 1 Item.
let tr = { transcript: '', dauer: 0, quelle: 'kein_audio' };
try { const a = $('Audio -> Transkript').first().json; if (a && (a.quelle === 'audio' || (a.transcript && a.transcript.length))) tr = a; } catch(e){}
if (tr.quelle !== 'audio') { try { const o = $('Ohne Audio').first().json; if (o) tr = o; } catch(e){} }
return [{ json: tr }];

// Ein Item pro hochgeladenem PDF (binary 'pdf').
const inp = $input.first();
const bin = inp.binary || {};
const items = [];
let idx = 0;
for (const [k, v] of Object.entries(bin)) {
  if (k.indexOf('pdf_') === 0) {
    items.push({ json: { pdf_index: idx, pdf_name: v.fileName || ('Dokument_' + (idx + 1)) }, binary: { pdf: v } });
    idx++;
  }
}
if (!items.length) items.push({ json: { pdf_index: 0, pdf_name: '(kein PDF)' }, binary: {} });
return items;

// Pro PDF: Textmenge bewerten, Original-PDF-Binary wiederherstellen, OCR-Bedarf markieren.
const src = $('PDFs auftrennen').item;
const cfg = $('Config').first().json.config;
const text = String($json.text || $json.data || '');
const hasPdf = !!(src.binary && src.binary.pdf);  // Platzhalter ohne PDF -> kein OCR
return { json: {
  pdf_index: src.json.pdf_index, pdf_name: src.json.pdf_name,
  text, text_len: text.trim().length,
  needs_ocr: hasPdf && text.trim().length < cfg.thresholds.pdf_min_chars
}, binary: src.binary };

// Baut pro Bildseite einen Vision-Request (qwen3-vl) zur woertlichen Textextraktion.
const cfg = $('Config').first().json.config;
const sources = $('PDF-Text bewerten').all().filter(it => it.json.needs_ocr);
const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const b = all[i].binary && all[i].binary.data;
  const mime = (b && b.mimeType) || 'image/png';
  const dataUrl = 'data:' + mime + ';base64,' + buf.toString('base64');
  const src = sources[i] || { json: {} };
  out.push({ json: {
    pdf_index: src.json.pdf_index != null ? src.json.pdf_index : i,
    pdf_name: src.json.pdf_name || ('Dokument_' + (i + 1)),
    requestBody: {
      model: cfg.vlm_model, temperature: 0, max_tokens: 2000, stream: false,
      messages: [
        { role: 'system', content: 'Du bist ein praeziser OCR-Assistent. Gib den gesamten lesbaren Text des Dokumentbildes woertlich und vollstaendig zurueck, ohne Kommentar, ohne Markdown.' },
        { role: 'user', content: [
          { type: 'text', text: 'Extrahiere den gesamten Text aus diesem Dokumentbild woertlich.' },
          { type: 'image_url', image_url: { url: dataUrl } }
        ] }
      ]
    }
  } });
}
return out;

// Vision-Antworten -> {pdf_index, pdf_name, text}.
const prompts = $('Vision-OCR Prompt').all();
const res = $input.all();
return res.map((it, i) => {
  const j = it.json; let c = '';
  if (j && j.choices && j.choices[0] && j.choices[0].message) c = j.choices[0].message.content || '';
  c = String(c).replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const p = prompts[i] ? prompts[i].json : {};
  return { json: { pdf_index: p.pdf_index != null ? p.pdf_index : i, pdf_name: p.pdf_name || ('Dokument_' + (i + 1)), text: c } };
});

// Alle Dokumenttexte (Text-Pfad + OCR-Pfad) nach Reihenfolge zu einem Block.
const items = $input.all();
const docs = items.map(it => it.json).filter(d => d && d.text != null)
  .sort((a, b) => (a.pdf_index || 0) - (b.pdf_index || 0));
const combined = docs.map(d => '### ' + (d.pdf_name || 'Dokument') + '\n' + (d.text || '')).join('\n\n');
return [{ json: { dokumente: combined, doc_count: docs.length, doc_names: docs.map(d => d.pdf_name) } }];

// Buendelt Transkript + Dokumenttext + Meta. Erste Lueckenpruefung (Dauer, PDF-Textmenge).
const cfg = $('Config').first().json.config;
let tr = { transcript: '', dauer: 0, quelle: 'kein_audio' };
try { tr = $('Transkript').first().json || tr; } catch(e){}
let ex = { dokumente: '', doc_count: 0 };
try { ex = $('Dokumente zusammenfuehren').first().json || ex; } catch(e){}
const meta = $('N00pre · Input-Qualitaetspruefung').first().json;
const transcript = tr.transcript || '';
const dauer = Number(tr.dauer || 0);
const doku = ex.dokumente || '';
const has_audio = tr.quelle === 'audio' && transcript.trim().length > 0;
const has_doku = doku.trim().length >= cfg.thresholds.pdf_min_chars;
const luecken = [];
if (!has_audio)
  luecken.push({ was: 'Keine Gespraechsaufnahme vorhanden', wo: 'N00',
    konsequenz: 'Analyse nur auf Dokumentbasis - GF-Aussagen, Ziele und Mengengeruest evtl. unvollstaendig.' });
else if (dauer && dauer < cfg.thresholds.audio_min_sek)
  luecken.push({ was: 'Audiodauer unter ' + (cfg.thresholds.audio_min_sek/60) + ' Min', wo: 'N00',
    konsequenz: 'Gespraechsinhalt evtl. unvollstaendig - Analyse weniger belastbar.' });
if (!has_doku)
  luecken.push({ was: 'Kein (lesbarer) Dokumenttext vorhanden', wo: 'N00b',
    konsequenz: (doku.trim().length > 0 ? 'Sehr wenig Text (' + doku.trim().length + ' Zeichen) - moeglicherweise Bild-PDF.' : 'Keine Dokumente - Analyse nur auf Gespraechsbasis.') });
// B2: Vom Anwender im Formular gesetzte Treiber - gelten als BELEGT (eine Quelle der Wahrheit fuer alle Nodes).
const cp = cfg.params; const anw = [];
if (cp.stundensatz_belegt) anw.push('Stundensatz ' + cp.stundensatz_eur + ' EUR/h');
if (cp.mandate_belegt) anw.push('Vorgaenge/Monat ' + cp.mandate_pro_monat);
if (cp.entwicklungsstunden_belegt) anw.push('Aufbau-/Entwicklungsstunden ' + cp.entwicklungsstunden);
anw.push('Verwendung: ' + (cp.nutzungsart === 'verkauf' ? ('Verkauf/Vermietung' + (cp.verkaufspreis ? ' zu ' + cp.verkaufspreis + ' EUR/Vorgang' : ' (Preis offen)')) : 'interne Prozessoptimierung (kein Verkauf)'));
return [{ json: {
  unternehmen: meta.Unternehmen || meta.unternehmen || '',
  datum: new Date().toISOString().slice(0, 10),
  anwender_eingaben: anw,
  transcript, dokumente: doku, dauer_sek: dauer, has_audio, has_doku, luecken_global: luecken
} }];

function parseLLM(nodeName){
  try {
    const r = $(nodeName).first().json;
    let c = (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
    if (typeof c !== 'string') c = JSON.stringify(c);
    const tEnd = c.lastIndexOf('</think>');
    if (tEnd !== -1) c = c.slice(tEnd + 8);            // alles bis inkl. letztem </think> verwerfen
    c = c.replace(/<think>[\s\S]*?<\/think>/g,'').replace(/```json|```/g,'');
    const s = c.indexOf('{'), e = c.lastIndexOf('}');
    return JSON.parse(s>=0 && e>s ? c.slice(s, e+1) : c);
  } catch(_) { return {}; }
}
const cfg = $('Config').first().json.config;
const ctx = $('Analyse-Kontext bauen').first().json;
const sys = "/no_think\nDu bist ein praeziser Wirtschaftlichkeits-Analyst fuer KMU. Du arbeitest streng faktenbasiert und erfindest NIEMALS Zahlen. Jede Zahl und jede Aussage erhaelt eine Kennzeichnung: 'Belegt' (direkt aus dem Input, mit Quelle), 'Geschaetzt' (abgeleitet, mit Herleitung), 'Annahme' (Standardannahme, nicht im Input vorhanden), 'Fehlend' (nicht verfuegbar, vor Entscheidung zu klaeren). MINDEST-PRINZIP: Wenn ein exakter Wert (noch) nicht ermittelbar ist, liefere die bestmoegliche begruendete Schaetzung - bevorzugt als Spanne (best/real/worst) - mit Kennzeichnung 'Geschaetzt' oder 'Annahme'. 'Fehlend' NUR, wenn es gar keine Grundlage fuer eine Schaetzung gibt. Liegen Bausteine vor (z.B. Zeitaufwand, Haeufigkeit, Stundensatz), MUSST du daraus rechnen statt 'Fehlend' zu setzen. AUSNAHME (wichtig): Bei NACHFRAGE- oder PREISABHAENGIGEN Groessen (kuenftiger Umsatz, Verkaufspreis, ob gesparte Zeit real verkauft/abgerechnet werden kann) ohne Beleg ist 'Fehlend' + Bedingung das KORREKTE Ergebnis - hier NICHT selbstsicher schaetzen. Eine erfundene Umsatz-/Preiszahl ist ein teurer Falsch-sicher-Fehler. Antworte AUSSCHLIESSLICH mit EINEM gueltigen JSON-Objekt nach dem vorgegebenen Schema. Kein Markdown, kein Codeblock, kein Fliesstext davor oder danach. Alle Inhalte auf Deutsch. Aufgabe: Kontext- und Prozessextraktion (Node N01).";
const usr = 'Extrahiere aus Transkript und Kundendokument den geschaeftlichen Kontext und die betroffenen Prozesse fuer eine Wirtschaftlichkeitsanalyse einer geplanten KI-/Automatisierungsloesung.\n' +
'Das analysierte Unternehmen lautet (aus dem Formular): "' + (ctx.unternehmen || 'unbekannt') + '". Verwende diesen Namen im Feld unternehmen, sofern die Quellen keinen anderen nennen.\n' +
'PFLICHT: Fuelle unternehmen, branche und groesse_hinweis IMMER aus. Leite Branche und Groesse aus den Quellen ab (Mindest-Prinzip - lieber begruendete Annahme/Schaetzung mit Kennzeichnung als leer). Diese drei Felder NIE leer lassen.\n\n' +
'Antworte als JSON mit Schema: {"unternehmen":"","branche":"","groesse_hinweis":"",' +
'"betroffene_prozesse":[{"name":"","beschreibung":"","haeufigkeit":"","heutiger_aufwand":""}],' +
'"ist_zustand":"","ziele":[""],"geplante_loesung":"","rahmenbedingungen":"",' +
'"kennzeichnungen":[{"wert":"","art":"Belegt|Geschaetzt|Annahme|Fehlend","quelle_oder_herleitung":""}],' +
'"luecken":[{"was":"","wo":"N01","konsequenz":""}]}\n\n' +
'=== TRANSKRIPT ===\n' + (ctx.transcript || '(keine Aufnahme)') + '\n\n=== KUNDENDOKUMENT ===\n' + (ctx.dokumente || '(kein Dokument)');
return [{ json: { requestBody: {
  model: cfg.llm_model, temperature: cfg.temperature,
  max_tokens: -1, stream: false,
  messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ]
} } }];

function parseLLM(nodeName){
  try {
    const r = $(nodeName).first().json;
    let c = (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
    if (typeof c !== 'string') c = JSON.stringify(c);
    const tEnd = c.lastIndexOf('</think>');
    if (tEnd !== -1) c = c.slice(tEnd + 8);            // alles bis inkl. letztem </think> verwerfen
    c = c.replace(/<think>[\s\S]*?<\/think>/g,'').replace(/```json|```/g,'');
    const s = c.indexOf('{'), e = c.lastIndexOf('}');
    return JSON.parse(s>=0 && e>s ? c.slice(s, e+1) : c);
  } catch(_) { return {}; }
}
const cfg = $('Config').first().json.config;
const ctx = $('Analyse-Kontext bauen').first().json;
const n01 = parseLLM('N01 · LLM');
const sys = "/no_think\nDu bist ein praeziser Wirtschaftlichkeits-Analyst fuer KMU. Du arbeitest streng faktenbasiert und erfindest NIEMALS Zahlen. Jede Zahl und jede Aussage erhaelt eine Kennzeichnung: 'Belegt' (direkt aus dem Input, mit Quelle), 'Geschaetzt' (abgeleitet, mit Herleitung), 'Annahme' (Standardannahme, nicht im Input vorhanden), 'Fehlend' (nicht verfuegbar, vor Entscheidung zu klaeren). MINDEST-PRINZIP: Wenn ein exakter Wert (noch) nicht ermittelbar ist, liefere die bestmoegliche begruendete Schaetzung - bevorzugt als Spanne (best/real/worst) - mit Kennzeichnung 'Geschaetzt' oder 'Annahme'. 'Fehlend' NUR, wenn es gar keine Grundlage fuer eine Schaetzung gibt. Liegen Bausteine vor (z.B. Zeitaufwand, Haeufigkeit, Stundensatz), MUSST du daraus rechnen statt 'Fehlend' zu setzen. AUSNAHME (wichtig): Bei NACHFRAGE- oder PREISABHAENGIGEN Groessen (kuenftiger Umsatz, Verkaufspreis, ob gesparte Zeit real verkauft/abgerechnet werden kann) ohne Beleg ist 'Fehlend' + Bedingung das KORREKTE Ergebnis - hier NICHT selbstsicher schaetzen. Eine erfundene Umsatz-/Preiszahl ist ein teurer Falsch-sicher-Fehler. Antworte AUSSCHLIESSLICH mit EINEM gueltigen JSON-Objekt nach dem vorgegebenen Schema. Kein Markdown, kein Codeblock, kein Fliesstext davor oder danach. Alle Inhalte auf Deutsch. Aufgabe: Bewertung Automatisierungsreife (Node N02).";
const basis = JSON.stringify(n01);
const usr = 'Bewerte die Automatisierungsreife des Vorhabens anhand von 8 Kriterien (Standardisierung, Regelbasiertheit, Datenverfuegbarkeit, Volumen/Haeufigkeit, Fehleranfaelligkeit heute, Schnittstellen, Stabilitaet des Prozesses, Akzeptanz). Vergib pro Kriterium 0-10 und einen Gesamtscore 0-10. Gib IMMER einen Gesamtscore ab, auch bei duenner Datenlage (dann konservativ schaetzen, art=Annahme). Antworte niemals leer.\n\n' +
'Uebernimm KEINE Kennzeichnungen oder Felder aus N01 - liefere nur deine eigene Reife-Bewertung.\n\n' +
'JSON-Schema: {"score":0,"kriterien":[{"name":"","wert":0,"begruendung":""}],"konfidenz":0.0,' +
'"luecken":[{"was":"","wo":"N02","konsequenz":""}]}\n\n=== KONTEXT (N01) ===\n' + basis;
return [{ json: { requestBody: {
  model: cfg.llm_model, temperature: cfg.temperature,
  max_tokens: -1, stream: false,
  messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ]
} } }];

function parseLLM(nodeName){
  try {
    const r = $(nodeName).first().json;
    let c = (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
    if (typeof c !== 'string') c = JSON.stringify(c);
    const tEnd = c.lastIndexOf('</think>');
    if (tEnd !== -1) c = c.slice(tEnd + 8);            // alles bis inkl. letztem </think> verwerfen
    c = c.replace(/<think>[\s\S]*?<\/think>/g,'').replace(/```json|```/g,'');
    const s = c.indexOf('{'), e = c.lastIndexOf('}');
    return JSON.parse(s>=0 && e>s ? c.slice(s, e+1) : c);
